-- generated by Art/Studio/Regions/kit.py from unstrip_region.lua.tmpl (2026-10-24): do not edit by hand.
-- Region Foundry: re-adds the CollectionService tags that finish.lua / restore.lua stripped into the attribute
-- RegionKitTags when they moved something into a RenseiBackups folder. Run in Studio Edit.
-- How to use it: name the subtree in ONE of two ways, then run this file.
--   * PATH below: the root's names from a service down, separated by "/", e.g.
--       "ServerStorage/RenseiBackups/Post-Region_Foundry_2026-10-24/Foundry/Buildings/House_row_1"
--   * or the attribute RegionKitUnstrip = true on each root (anywhere in workspace or ServerStorage), e.g. on a piece
--     you have just dragged out of a backup into the map. Leave PATH nil for this.
-- Every root and all its descendants get their tags back, RegionKitTags (and RegionKitUnstrip) is cleared, and it
-- returns how many instances were re-tagged. It refuses, changing nothing, when PATH names nothing or no root is
-- marked. A re-tagged piece left inside ServerStorage becomes visible to services' GetTagged again: move it out.
local HS = game:GetService("HttpService")
local CS = game:GetService("CollectionService")

local PATH = nil -- e.g. "ServerStorage/RenseiBackups/Post-Region_..._<date>/<MapChild>/<Group>/<Model>"

local Roots = {}
if PATH then
	local Node
	for Name in string.gmatch(PATH, "[^/]+") do
		if not Node then
			local Ok, S = pcall(function() return game:GetService(Name) end)
			Node = Ok and S or game:FindFirstChild(Name)
		else
			Node = Node:FindFirstChild(Name)
		end
		if not Node then return "unstrip refused: " .. PATH .. " names nothing (stopped at " .. Name .. "); nothing changed" end
	end
	table.insert(Roots, Node)
else
	for _, Top in ipairs({workspace, game:GetService("ServerStorage")}) do
		for _, D in ipairs(Top:GetDescendants()) do
			if D:GetAttribute("RegionKitUnstrip") == true then table.insert(Roots, D) end
		end
	end
	if #Roots == 0 then return "unstrip refused: set PATH, or the attribute RegionKitUnstrip = true on a root; nothing changed" end
end

local N, Names = 0, {}
local function One(D)
	local J = D:GetAttribute("RegionKitTags")
	if J then
		for _, Tag in ipairs(HS:JSONDecode(J)) do CS:AddTag(D, Tag) end
		D:SetAttribute("RegionKitTags", nil)
		N += 1
	end
end
for _, R in ipairs(Roots) do
	R:SetAttribute("RegionKitUnstrip", nil)
	One(R)
	for _, D in ipairs(R:GetDescendants()) do One(D) end
	table.insert(Names, R:GetFullName())
end
return ("unstrip: %d instances re-tagged under %s"):format(N, table.concat(Names, ", "))
